urlset:

    {{ site_url }}/
    1.0


    {{ site_url }}/blog/
    {% if latest_article %}{{ latest_article.date|date:"Y-m-d" }}{% endif %}
    weekly
    0.8

{% for article in articles %}

    {{ site_url }}{% url 'content:article' slug=article.slug %}
    {{ article.date|date:"Y-m-d" }}
    monthly
    0.7

{% endfor %}
